window.CC.p.push({n:7,view:"<section class=\"view\" id=\"p7\" hidden style=\"--c:#0097a7\"><h1><i>7</i>ENT</h1><p class=\"lead\">30 sections — pick what you want to read.</p><div class=\"grid\"><h3 class=\"sg\">Part 7A</h3><div class=\"card\" data-u=\"u142\"><button class=\"open\" data-u=\"u142\"><b>Case 1</b><span>Acute Otitis Media (AOM)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Otitis+Media+%28AOM%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u143\"><button class=\"open\" data-u=\"u143\"><b>Case 2</b><span>Otitis Media with Effusion (OME / &quot;GLUE EAR&quot;)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Otitis+Media+with+Effusion+%28OME+%2F+%22GLUE+EAR%22%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u144\"><button class=\"open\" data-u=\"u144\"><b>Case 3</b><span>Chronic Suppurative Otitis Media (CSOM) &amp; Cholesteatoma</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Chronic+Suppurative+Otitis+Media+%28CSOM%29+%26+Cholesteatoma\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u145\"><button class=\"open\" data-u=\"u145\"><b>Case 4</b><span>Otitis Externa (&quot;SWIMMERʼS EAR&quot;) &amp; Malignant Otitis Externa</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Otitis+Externa+%28%22SWIMMER%CA%BCS+EAR%22%29+%26+Malignant+Otitis+Externa\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u146\"><button class=\"open\" data-u=\"u146\"><b>Case 5</b><span>Otomycosis (FUNGAL EAR INFECTION — EGYPTIAN CLINIC STAPLE)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Otomycosis+%28FUNGAL+EAR+INFECTION+%E2%80%94+EGYPTIAN+CLINIC+STAPLE%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u147\"><button class=\"open\" data-u=\"u147\"><b>Case 6</b><span>Cerumen Impaction &amp; External EAR Canal Foreign Body</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cerumen+Impaction+%26+External+EAR+Canal+Foreign+Body\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u148\"><button class=\"open\" data-u=\"u148\"><b>Case 7</b><span>Hearing Loss Approach &amp; Sudden Sensorineural Hearing Loss (SSNHL)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hearing+Loss+Approach+%26+Sudden+Sensorineural+Hearing+Loss+%28SSNHL%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u149\"><button class=\"open\" data-u=\"u149\"><b>Case 8</b><span>Presbycusis, Noise-Induced Hearing Loss &amp; Otosclerosis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Presbycusis%2C+Noise-Induced+Hearing+Loss+%26+Otosclerosis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u150\"><button class=\"open\" data-u=\"u150\"><b>Case 9</b><span>Vertigo Approach — BPPV, Ménièreʼs &amp; Vestibular Neuritis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Vertigo+Approach+%E2%80%94+BPPV%2C+M%C3%A9ni%C3%A8re%CA%BCs+%26+Vestibular+Neuritis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u151\"><button class=\"open\" data-u=\"u151\"><b>Case 10</b><span>Epistaxis (NOSEBLEED — ANTERIOR VS. POSTERIOR)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Epistaxis+%28NOSEBLEED+%E2%80%94+ANTERIOR+VS.+POSTERIOR%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u152\"><button class=\"open\" data-u=\"u152\"><b>Case 11</b><span>Allergic Rhinitis &amp; Non-Allergic / Rhinitis Medicamentosa</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Allergic+Rhinitis+%26+Non-Allergic+%2F+Rhinitis+Medicamentosa\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u153\"><button class=\"open\" data-u=\"u153\"><b>Case 12</b><span>Acute Viral vs. Acute Bacterial Rhinosinusitis (ABRS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Viral+vs.+Acute+Bacterial+Rhinosinusitis+%28ABRS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u154\"><button class=\"open\" data-u=\"u154\"><b>Case 13</b><span>Chronic Rhinosinusitis &amp; Nasal Polyps</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Chronic+Rhinosinusitis+%26+Nasal+Polyps\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u155\"><button class=\"open\" data-u=\"u155\"><b>Case 14</b><span>Deviated Nasal Septum, Septal Hematoma &amp; Nasal Fracture</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Deviated+Nasal+Septum%2C+Septal+Hematoma+%26+Nasal+Fracture\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u156\"><button class=\"open\" data-u=\"u156\"><b>Case 15</b><span>Pediatric Nasal Foreign Body &amp; Choanal Atresia</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Nasal+Foreign+Body+%26+Choanal+Atresia\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><h3 class=\"sg\">Part 7B</h3><div class=\"card\" data-u=\"u157\"><button class=\"open\" data-u=\"u157\"><b>Case 16</b><span>Acute Pharyngitis &amp; Tonsillitis (VIRAL VS. GAS — CENTOR CRITERIA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Pharyngitis+%26+Tonsillitis+%28VIRAL+VS.+GAS+%E2%80%94+CENTOR+CRITERIA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u158\"><button class=\"open\" data-u=\"u158\"><b>Case 17</b><span>Peritonsillar Abscess (QUINSY) &amp; Retropharyngeal Abscess</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Peritonsillar+Abscess+%28QUINSY%29+%26+Retropharyngeal+Abscess\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u159\"><button class=\"open\" data-u=\"u159\"><b>Case 18</b><span>Adenotonsillar Hypertrophy &amp; Tonsillectomy Indications</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Adenotonsillar+Hypertrophy+%26+Tonsillectomy+Indications\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u160\"><button class=\"open\" data-u=\"u160\"><b>Case 19</b><span>Ludwigʼs Angina (BILATERAL SUBMANDIBULAR CELLULITIS — AIRWAY EMERGENCY!)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ludwig%CA%BCs+Angina+%28BILATERAL+SUBMANDIBULAR+CELLULITIS+%E2%80%94+AIRWAY+EMERGENCY%21%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u161\"><button class=\"open\" data-u=\"u161\"><b>Case 20</b><span>Acute &amp; Chronic Laryngitis + Vocal Cord Nodules &amp; Polyps</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+%26+Chronic+Laryngitis+%2B+Vocal+Cord+Nodules+%26+Polyps\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u162\"><button class=\"open\" data-u=\"u162\"><b>Case 21</b><span>Vocal Cord Paralysis (UNILATERAL VS. BILATERAL)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Vocal+Cord+Paralysis+%28UNILATERAL+VS.+BILATERAL%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u163\"><button class=\"open\" data-u=\"u163\"><b>Case 22</b><span>Laryngeal Carcinoma (THE HOARSENESS RED FLAG!)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Laryngeal+Carcinoma+%28THE+HOARSENESS+RED+FLAG%21%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u164\"><button class=\"open\" data-u=\"u164\"><b>Case 23</b><span>Nasopharyngeal Carcinoma (NPC)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Nasopharyngeal+Carcinoma+%28NPC%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u165\"><button class=\"open\" data-u=\"u165\"><b>Case 24</b><span>Neck Masses Approach (&quot;RULE OF 7s&quot; &amp; CONGENITAL CYSTS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Neck+Masses+Approach+%28%22RULE+OF+7s%22+%26+CONGENITAL+CYSTS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u166\"><button class=\"open\" data-u=\"u166\"><b>Case 25</b><span>Salivary Gland Disorders — Sialolithiasis &amp; Suppurative Parotitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Salivary+Gland+Disorders+%E2%80%94+Sialolithiasis+%26+Suppurative+Parotitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u167\"><button class=\"open\" data-u=\"u167\"><b>Case 26</b><span>Salivary Gland Tumors (&quot;80% RULE&quot;)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Salivary+Gland+Tumors+%28%2280%25+RULE%22%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u168\"><button class=\"open\" data-u=\"u168\"><b>Case 27</b><span>Dysphagia &amp; Esophageal Foreign Body / Button Battery Emergency</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dysphagia+%26+Esophageal+Foreign+Body+%2F+Button+Battery+Emergency\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u169\"><button class=\"open\" data-u=\"u169\"><b>Case 28</b><span>Caustic Esophageal Ingestion (ALKALI VS. ACID)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Caustic+Esophageal+Ingestion+%28ALKALI+VS.+ACID%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u170\"><button class=\"open\" data-u=\"u170\"><b>Case 29</b><span>Facial Nerve (CN VII) Palsy — Bellʼs Palsy vs. Central Stroke</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Facial+Nerve+%28CN+VII%29+Palsy+%E2%80%94+Bell%CA%BCs+Palsy+vs.+Central+Stroke\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u171\"><button class=\"open\" data-u=\"u171\"><b>Case 30</b><span>Tracheostomy Care &amp; Acute Tracheostomy Emergencies</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Tracheostomy+Care+%26+Acute+Tracheostomy+Emergencies\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div></div></section>",units:"<article class=\"view unit\" id=\"u142\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 1</span><h1>Acute Otitis Media (AOM)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Otitis+Media+%28AOM%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><b>AOM</b> (Acute Otitis Media) is an acute, suppurative bacterial or viral infection of the middle ear cleft (mucoperiosteal lining of the middle ear and mastoid air cells), presenting with <b>rapid-onset signs of middle ear inflammation AND effusion</b>. <i>(Peak age: </i><i><b>6–24 months</b></i><i>; #1 reason for antibiotic prescriptions in children!)</i></p><h3><b>2. Etiology &amp; Risk Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Anatomical &amp; Host Factors (Children):</b> Shorter, wider, and <b>more horizontal Eustachian tube</b> in infants/toddlers allowing easy nasopharyngeal reflux; adenoid hypertrophy; cleft palate; immunodeficiency; lack of breastfeeding.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Environmental Triggers:</b> Preceding <b>viral URTI</b> (Upper Respiratory Tract Infection — causes Eustachian tube edema &amp; negative middle ear pressure!), daycare attendance, <b>bottle-feeding while lying supine</b>, secondhand tobacco smoke exposure.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Microbiology (Pathogens):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Viral (~30%):</i> <b>RSV</b> (Respiratory Syncytial Virus), Rhinovirus, Influenza, Adenovirus.</li>\n<li class=\"l2\"><i>Bacterial (~70%):</i> <i><b>Streptococcus pneumoniae</b></i> (#1 overall!), <b>Nontypeable </b><i><b>Haemophilus influenzae</b></i> (linked to <b>concurrent purulent conjunctivitis — \"Otitis-Conjunctivitis Syndrome\"</b>!), and <i><b>Moraxella catarrhalis</b></i>.</li>\n</ul><h3><b>3. Pathophysiology</b></h3><p>Viral URTI swells the Eustachian tube mucosa -&gt; blocks middle ear ventilation -&gt; negative pressure pulls nasopharyngeal bacteria/fluid into the middle ear -&gt; trapped secretions suppurate -&gt; pus pushes against the <b>TM</b> (Tympanic Membrane), causing severe pain and potential perforation.</p><h3><b>4. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Symptoms:</b> Acute <b>otalgia</b> (ear pain — infants pull/tug at ear, cry inconsolably, irritable, poor sleep/feeding), <b>fever</b>, conductive hearing loss; <b>sudden relief of pain accompanied by purulent otorrhea</b> if the eardrum perforates!</li>\n<li class=\"l1\"><b>Otoscopy (Gold Standard Exam):</b></li>\n<li class=\"l2\"><b>Bulging, erythematous, opaque TM</b> (Tympanic Membrane) with <b>loss of the normal light reflex (cone of light)</b> and obscured bony landmarks (malleus) + <b>decreased/absent mobility</b> on pneumatic otoscopy!</li>\n<li class=\"l2\"><i>(TRAP: Mild redness of the TM alone in a crying febrile child WITHOUT bulging or effusion is NOT AOM — crying causes vasodilation!)</i></li>\n</ul><h3><b>5. Investigations &amp; Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\"><b>Diagnosis:</b> Purely <b>Clinical</b> via Otoscopy (no routine labs or imaging unless intracranial complications suspected!).</li>\n<li class=\"l1\"><b>DDx:</b> <b>OME</b> (Otitis Media with Effusion — fluid <i>without</i> acute bulging/fever/severe pain!), <b>Otitis Externa</b> (pain on pulling pinna/tragus!), Viral myringitis, Referred otalgia (teething, pharyngitis, <b>TMJ</b> [Temporomandibular Joint] dysfunction).</li>\n</ul><h3><b>6. Complications</b></h3><ul>\n<li class=\"l1\"><b>Intratemporal:</b> Tympanic membrane perforation (usually heals spontaneously!), <b>Acute Mastoiditis</b> (postauricular redness, tenderness, fluctuance, and <b>pinna pushed downward &amp; outward</b>!), Facial nerve (CN VII) palsy, Labyrinthitis.</li>\n<li class=\"l1\"><b>Intracranial (Rare, Life-Threatening):</b> <mark class=\"hl lab\"><b>Meningitis</b></mark> , Brain abscess (temporal lobe/cerebellum), Lateral (sigmoid) sinus thrombosis.</li>\n</ul><h3><b>7. Treatment (AAP Guidelines: Watchful Waiting vs. Immediate Antibiotics!)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Analgesia FIRST (Mandatory in ALL Patients!):</b></mark> Oral <b>Ibuprofen</b> (10 mg/kg) or <b>Acetaminophen</b> (15 mg/kg). <i>(Avoid topical benzocaine in perforated TM or infants &lt; 2 yrs!).</i></li>\n<li class=\"l1\"><b>When to Give Immediate Antibiotics:</b></li>\n<li class=\"l2\">ALL children <b>&lt; 6 months</b>.</li>\n<li class=\"l2\">Children <b>6–24 months</b> with <b>bilateral AOM</b> or severe symptoms (<b>moderate-severe pain &gt; 48 hrs or fever ≥ 39°C</b>).</li>\n<li class=\"l2\">Children <b>≥ 2 years</b> ONLY if <b>severe symptoms</b>, toxic appearance, otorrhea (perforation), or immunocompromised! <i>(Otherwise, </i><i><b>48–72 hr Watchful Waiting</b></i><i> in healthy children &gt; 2 yrs with mild unilateral AOM!).</i></li>\n<li class=\"l1\"><b>Antibiotic Choice:</b></li>\n<li class=\"l2\"><b>First-Line:</b> <mark class=\"hl rx\"><b>High-Dose Oral Amoxicillin (80–90 mg/kg/day divided BID)</b></mark> (covers penicillin-resistant <i>S. pneumoniae</i>!). <i>(Duration: 10 days if &lt; 2 yrs or severe; 5–7 days if ≥ 6 yrs mild).</i></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Second-Line (Use if Amoxicillin in past 30 days, concurrent Purulent Conjunctivitis [</b></mark><i><b>H. influenzae</b></i><mark class=\"hl rx\"><b>!], or failed at 48–72 hrs):</b></mark> <mark class=\"hl rx\"><b>High-Dose Amoxicillin-Clavulanate (90 mg/kg/day of amoxicillin)</b></mark> or <mark class=\"hl rx\"><b>IM/IV Ceftriaxone</b></mark> (50 mg/kg × 1–3 days).</li>\n<li class=\"l2\"><i>Penicillin Allergy:</i> Cefdinir/Cefuroxime (non-anaphylactic) or Azithromycin/Clindamycin (if severe anaphylaxis).</li>\n</ul>\n<p>[Image Reference Suggestion]: <b>Otoscopy Comparison</b> showing <b>Normal Pearly-Gray TM (with Cone of Light)</b> vs. <b>Acute Otitis Media (Bulging Erythematous TM)</b>.</p><nav class=\"un\"><span></span><button class=\"nv\" data-u=\"u143\">Case 2 →</button></nav></article><article class=\"view unit\" id=\"u143\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 2</span><h1>Otitis Media with Effusion (OME / &quot;GLUE EAR&quot;)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Otitis+Media+with+Effusion+%28OME+%2F+%22GLUE+EAR%22%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Presence of <b>non-purulent fluid (serous or mucoid effusion) in the middle ear WITHOUT signs or symptoms of acute infection</b> (no fever, no acute severe ear pain, no bulging red TM). <b>#1 Cause of Acquired Hearing Loss in Children!</b></p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Post-AOM Persistent Fluid (Most Common):</b> Middle ear fluid persists for weeks–3 months after acute infection resolves.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Chronic Eustachian Tube Dysfunction:</b> <b>Adenoid hypertrophy</b> (children), allergic rhinitis, cleft palate.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>CRITICAL ADULT RED FLAG:</b> <b>Unilateral OME in an Adult</b> (especially with nasal obstruction/epistaxis/neck node) = <b>NASOPHARYNGEAL CARCINOMA</b> obstructing the Eustachian tube orifice until proven otherwise!</span></p><h3><b>3. Clinical Picture &amp; Investigations</b></h3><ul>\n<li class=\"l1\">Often silent! Children present with <b>decreased hearing</b> (\"turns TV volume up\", asks \"what?\", inattentiveness at school, <b>speech delay</b>!), mild ear fullness/popping (\"clogged ear\").</li>\n<li class=\"l1\"><b>Otoscopy:</b> <b>Retracted, dull amber/yellowish TM</b> with visible <b>air-fluid level or air bubbles</b> behind the eardrum + <b>immobile TM</b> on pneumatic otoscopy!</li>\n<li class=\"l1\"><b>Audiometry / Tympanometry:</b> <b>Conductive Hearing Loss</b> + <b>Flat \"Type B\" Tympanogram</b>!</li>\n</ul><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Children:</b> <b>~80–90% Resolve Spontaneously Within 3 Months!</b> -&gt; <b>Watchful Waiting for 3 Months</b> (<b>Antibiotics, Antihistamines, Decongestants, and Oral Steroids are INEFFECTIVE and NOT recommended!</b>).</li>\n<li class=\"l2\"><i>Indications for Surgery (</i><i><b>Tympanostomy Tubes [Grommets] +/- Adenoidectomy</b></i><i>):</i> Bilateral OME persisting <b>&gt; 3 months WITH documented Hearing Loss (&gt; 20– 40 dB) or Speech/Academic Delay</b>, or structural TM retraction pocket!</li>\n<li class=\"l1\"><b>Adults With Unilateral OME:</b> <b>IMMEDIATE Nasal Endoscopy (Rigid/Flexible Nasopharyngoscopy)</b> to rule out <mark class=\"hl lab\"><b>Nasopharyngeal Carcinoma</b></mark> !</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u142\">← Case 1</button><button class=\"nv\" data-u=\"u144\">Case 3 →</button></nav></article><article class=\"view unit\" id=\"u144\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 3</span><h1>Chronic Suppurative Otitis Media (CSOM) &amp; Cholesteatoma</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Chronic+Suppurative+Otitis+Media+%28CSOM%29+%26+Cholesteatoma\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Chronic inflammation of the middle ear and mastoid with <b>persistent tympanic membrane perforation</b> and <b>recurrent/persistent otorrhea (&gt; 6–12 weeks)</b>, critically divided into <b>Safe (Tubotympanic)</b> vs. <b>Unsafe (Atticoantral / Cholesteatoma)</b>.</p><h3><b>2. Crucial Comparison: Safe vs. Unsafe (Cholesteatoma)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Safe (Tubotympanic) CSOM</b></p></th><th><p><mark class=\"hl dx\"><b>Unsafe (Atticoantral) CSOM — CHOLESTEATOMA!</b></mark></p></th></tr><tr><td><p><b>Pathology</b></p></td><td><p>Benign mucosal disease (<b>central perforation</b> in <i>pars tensa</i>)</p></td><td><p>Destructive sac of <b>keratinizing squamous epithelium</b> inside middle ear/mastoid eroding bone via collagenase!</p></td></tr><tr><td><p><b>Perforation Site</b></p></td><td><p><b>Central perforation</b> (surrounded by intact rim/annulus!)</p></td><td><p><b>Marginal (posterosuperior)</b> or <b>Attic (</b><i><b>pars flaccida</b></i><b>)</b> perforation!</p></td></tr><tr><td><p><b>Discharge (Otorrhea)</b></p></td><td><p><mark class=\"hl dx\"><b>Copious, mucoid/mucopurulent, ODORLESS</b></mark> , intermittent (flares with URTIs/water entry!)</p></td><td><p><b>Scant, persistent, FOUL-SMELLING (\"fetid/cheesy\") purulent discharge</b> + pearly-white keratin debris/crust in attic!</p></td></tr><tr><td></td><td><p>with URTIs/water entry!)</p></td><td><p><b>discharge</b> + pearly-white keratin debris/crust in attic!</p></td></tr><tr><td><p><b>Complication Risk</b></p></td><td><p>Low (mild-moderate conductive hearing loss)</p></td><td><p><b>HIGH RISK OF BONE EROSION:</b> Ossicular destruction, <b>Mastoiditis</b>, <b>Labyrinthine fistula (vertigo on pressing tragus!)</b>, <b>CN VII Facial Palsy</b>, <mark class=\"hl lab\"><b>Brain Abscess / Meningitis</b></mark> !</p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p><b>Dry ear precautions</b> (keep water out!) + <mark class=\"hl rx\"><b>Topical Fluoroquinolone drops (Ciprofloxacin/Ofloxacin)</b></mark> -&gt; <b>Elective Tympanoplasty (Myringoplasty)</b> once dry!</p></td><td><p><mark class=\"hl mech\"><b>URGENT CT Temporal Bone + SURGICAL MASTOIDECTOMY</b></mark> to completely eradicate cholesteatoma and prevent intracranial death!</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u143\">← Case 2</button><button class=\"nv\" data-u=\"u145\">Case 4 →</button></nav></article><article class=\"view unit\" id=\"u145\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 4</span><h1>Otitis Externa (&quot;SWIMMERʼS EAR&quot;) &amp; Malignant Otitis Externa</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Otitis+Externa+%28%22SWIMMER%CA%BCS+EAR%22%29+%26+Malignant+Otitis+Externa\">🔍 Search on Google</a></header><h3><b>A. Acute Otitis Externa (\"Swimmer’s Ear\")</b></h3><ul>\n<li class=\"l1\"><b>Definition &amp; Etiology:</b> Diffuse bacterial infection of the <b>EAC</b> (External Auditory Canal) skin, triggered by trapped swimming/bath water (alkalinizes protective acidic ear canal), cotton-swab trauma, or hearing aids.</li>\n<li class=\"l1\"><b>Pathogens:</b> <i><b>Pseudomonas aeruginosa</b></i> (#1!) and <i><b>Staphylococcus aureus</b></i>.</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Severe ear pain (<b>exquisitely worsened by PULLING THE PINNA or PRESSING THE TRAGUS — Hallmark distinguishing sign from AOM!</b>), itching, scant discharge, <b>swollen erythematous/narrowed ear canal</b> (TM often normal if visible!).</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\">Gentle <b>aural toilet/suctioning</b> of debris.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Topical Antibiotic + Steroid Ear Drops</b> (<mark class=\"hl rx\"><b> Ciprofloxacin + Dexamethasone</b></mark> or <b>Ofloxacin</b> drops × 7 days — <i>safe even if TM perforation status is unknown!</i> Avoid Neomycin if TM perforated due to ototoxicity!). If canal completely swollen shut -&gt; insert an <b>Ear Wick (Merocel)</b> to deliver drops!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Dry ear precautions</b> (cotton ball coated with Vaseline while showering!). <i>(Oral antibiotics NOT needed unless spreading cellulitis!).</i></span></p><h3><b>B. Malignant (Necrotizing) Otitis Externa (LIFE-THREATENING EMERGENCY!)</b></h3><ul>\n<li class=\"l1\"><b>Classic Patient:</b> <b>ELDERLY UNCONTROLLED DIABETIC</b> (or immunocompromised) patient!</li>\n<li class=\"l1\"><b>Pathogen:</b> Invasive <i><b>Pseudomonas aeruginosa</b></i> causing <b>skull-base osteomyelitis</b>!</li>\n<li class=\"l1\"><b>Clinical Red Flags:</b> <mark class=\"hl dx\"><b>EXCRUCIATING, RELENTLESS DEEP EAR PAIN WORSE AT NIGHT</b></mark> , <b>Granulation Tissue on floor of EAC</b> (at bony-cartilaginous junction!), failing standard ear drops, and <b>Cranial Nerve VII (Facial) Palsy</b> (later CN IX, X, XI!).</li>\n<li class=\"l1\"><b>Investigations &amp; Treatment:</b> <mark class=\"hl mech\"><b>Elevated ESR/CRP</b></mark> , <b>CT Temporal Bone</b> (bony erosion) + <mark class=\"hl mech\"><b>MRI</b></mark> , Biopsy granulation tissue (rule out Squamous Cell Carcinoma!). <mark class=\"hl rx\"><b>Admit Immediately -&gt; Prolonged IV Antipseudomonal Antibiotics (Ciprofloxacin / Cefepime / Piperacillin-Tazobactam / Meropenem × 6 weeks!)</b></mark> + strict glycemic control!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u144\">← Case 3</button><button class=\"nv\" data-u=\"u146\">Case 5 →</button></nav></article><article class=\"view unit\" id=\"u146\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 5</span><h1>Otomycosis (FUNGAL EAR INFECTION — EGYPTIAN CLINIC STAPLE)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Otomycosis+%28FUNGAL+EAR+INFECTION+%E2%80%94+EGYPTIAN+CLINIC+STAPLE%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Etiology</b></h3><p>Superficial fungal infection of the external auditory canal, <b>extremely common in Egypt</b> due to hot humid summers, swimming, and <b>overuse of topical antibiotic/steroid ear drops</b>!</p>\n<ul>\n<li class=\"l1\"><b>Pathogens:</b> <i><b>Aspergillus niger</b></i> (#1 — black/gray spores!) and <i><b>Candida albicans</b></i> (white cheesy debris!).</li>\n</ul><h3><b>2. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>INTENSE, RELENTLESS EAR ITCHING (Pruritus — #1 Symptom!)</b></mark> , ear blockage/fullness, mild discomfort (less painful than bacterial otitis externa unless superinfected!).</li>\n<li class=\"l1\"><b>Pathognomonic Otoscopy:</b> Canal filled with <b>white/grayish mass dotted with black fungal spores resembling \"WET NEWSPAPER\" or \"FLUFFY COTTON\"</b>!</li>\n</ul><h3><b>3. Treatment</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>MOST IMPORTANT STEP — Thorough Aural Toilet / Suctioning</b> under microscope/otoscope (antifungal drops cannot penetrate thick fungal debris!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Keep Ear Strictly Dry!</b> (No water, no cotton swabs!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Topical Antifungal Drops:</b> <b>Clotrimazole 1% solution</b> (or Miconazole / Flumethasone-Clioquinol / Boric acid-alcohol drops) TID for <b>2–3 weeks</b> (continue 1 week after resolution to prevent relapse!). <i>Stop all antibiotic-steroid ear drops!</i></span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u145\">← Case 4</button><button class=\"nv\" data-u=\"u147\">Case 6 →</button></nav></article><article class=\"view unit\" id=\"u147\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 6</span><h1>Cerumen Impaction &amp; External EAR Canal Foreign Body</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cerumen+Impaction+%26+External+EAR+Canal+Foreign+Body\">🔍 Search on Google</a></header><h3><b>A. Cerumen (Earwax) Impaction</b></h3><ul>\n<li class=\"l1\"><b>Symptoms:</b> Conductive hearing loss (especially sudden right after showering/swimming when wax swells!), ear fullness, tinnitus.</li>\n<li class=\"l1\"><b>Treatment (3 Safe Methods):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Cerumenolytic Drops</b> (Olive oil, Mineral oil, Carbamide peroxide, or Sodium bicarbonate drops for 3–5 days).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Warm Water Irrigation/Syringing</b> — <b>CONTRAINDICATED if:</b> Suspected/known <b>TM perforation</b>, <b>tympanostomy tubes</b>, history of ear surgery, <b>organic/hygroscopic FB</b> (beans/peas swell!), or active otitis externa!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Manual Removal under Direct Vision</b> (Curette/Alligator forceps/Microsuction — safest when TM status unknown!).</span></p><h3><b>B. Foreign Body in External Ear Canal (Children!)</b></h3><ul>\n<li class=\"l1\"><b>LIVE INSECT IN EAR (Cockroach/Fly — Common ER Panic!):</b></li>\n<li class=\"l2\"><b>Step 1:</b> <b>KILL THE INSECT FIRST</b> by filling the ear canal with <mark class=\"hl rx\"><b>Mineral Oil, Olive Oil, or 2% Lidocaine</b></mark> (stops painful wing-beating against eardrum!).</li>\n<li class=\"l2\"><b>Step 2:</b> Gently remove with alligator forceps or warm irrigation once dead!</li>\n<li class=\"l1\"><b>Button Battery in Ear:</b> <b>EMERGENT REMOVAL IMMEDIATELY</b> (<b>DO NOT irrigate</b> — moisture accelerates alkaline liquefaction necrosis of canal/TM!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u146\">← Case 5</button><button class=\"nv\" data-u=\"u148\">Case 7 →</button></nav></article><article class=\"view unit\" id=\"u148\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 7</span><h1>Hearing Loss Approach &amp; Sudden Sensorineural Hearing Loss (SSNHL)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hearing+Loss+Approach+%26+Sudden+Sensorineural+Hearing+Loss+%28SSNHL%29\">🔍 Search on Google</a></header><h3><b>1. Conductive Hearing Loss (CHL) vs. Sensorineural Hearing Loss (SNHL)</b></h3><ul>\n<li class=\"l1\"><b>CHL (Outer or Middle Ear Problem):</b> Cerumen impaction, Foreign body, Otitis externa, AOM, OME, TM perforation, <b>Otosclerosis</b>, Ossicular disruption, Cholesteatoma.</li>\n<li class=\"l1\"><b>SNHL (Inner Ear [Cochlea] or CN VIII / Auditory Pathway):</b> Presbycusis, Noise-induced, <b>Ototoxic drugs</b> (Aminoglycosides, Loop diuretics, Cisplatin, High-dose Aspirin), <b>Ménière’s</b>, <b>Vestibular Schwannoma (Acoustic Neuroma)</b>, Post-Meningitis, <b>SSNHL</b>.</li>\n</ul><h3><b>2. Tuning Fork Mastery (512-Hz Tuning Fork — Rinne &amp; Weber Tests!)</b></h3><table class=\"t \"><tr><td><p><mark class=\"hl lab\"><b>Test</b></mark></p></td><td><p><b>Normal Hearing</b></p></td><td><p><b>Conductive Loss (CHL — e.g., Left Wax/OME)</b></p></td><td><p><b>Sensorineural Loss (SNHL — e.g., Left CN VIII)</b></p></td></tr><tr><td><p><b>Rinne Test</b> <i>(Air Conduction [AC] vs. Bone Conduction [BC] on Mastoid)</i></p></td><td><p><b>Positive (AC &gt; BC)</b> bilaterally</p></td><td><p><b>NEGATIVE (BC &gt; AC)</b> in the <b>affected (Left) ear</b>!</p></td><td><p><b>Positive (AC &gt; BC)</b> in <b>BOTH</b> ears (both reduced equally in Left!)</p></td></tr><tr><td><p><b>Weber Test</b> <i>(Base on Midline Forehead/Vertex)</i></p></td><td><p>Sound heard <b>equally in midline</b></p></td><td><p><b>Lateralizes TO THE AFFECTED (LEFT) EAR! </b><i>(Lack of ambient room masking noise makes bone sound louder!)</i></p></td><td><p><mark class=\"hl mech\"><b>Lateralizes TO THE HEALTHY (RIGHT) EAR!</b></mark></p></td></tr></table><h3><b>3. SUDDEN SENSORINEURAL HEARING LOSS (SSNHL — TRUE OTOLOGIC EMERGENCY!)</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Rapid-onset <b>≥ 30 dB SNHL</b> across ≥ 3 consecutive frequencies developing over <b>≤ 72 hours</b> (patient wakes up suddenly deaf in one ear — often misdiagnosed as \"just wax/fluid\"!).</li>\n<li class=\"l1\"><b>Etiology:</b> Mostly idiopathic (viral cochleitis/vascular), <i>must rule out </i><i><b>Vestibular Schwannoma (Acoustic Neuroma)</b></i><i> via </i><mark class=\"hl mech\"><i><b>MRI Brain/IAC with Gadolinium</b></i></mark><i> !</i></li>\n<li class=\"l1\"><b>URGENT TREATMENT (Golden Window: Within 1–2 Weeks!):</b> Confirm SNHL urgently via Tuning Forks + <b>Pure-Tone Audiometry</b> -&gt; Start <mark class=\"hl rx\"><b>High-Dose Oral Prednisone (1 mg/kg/day, max 60 mg) for 10–14 days</b></mark> (and/or <mark class=\"hl rx\"><b>Intratympanic Dexamethasone injections</b></mark> )!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u147\">← Case 6</button><button class=\"nv\" data-u=\"u149\">Case 8 →</button></nav></article><article class=\"view unit\" id=\"u149\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 8</span><h1>Presbycusis, Noise-Induced Hearing Loss &amp; Otosclerosis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Presbycusis%2C+Noise-Induced+Hearing+Loss+%26+Otosclerosis\">🔍 Search on Google</a></header><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Presbycusis (Age-Related Hearing Loss):</b> Most common adult SNHL (&gt; 60 yrs); progressive bilateral symmetric <b>HIGH-FREQUENCY SNHL</b> (difficulty hearing women/children’s voices &amp; understanding speech in noisy restaurants -&gt; <b>\"Cocktail Party Problem\"</b>!). <i>Treat:</i> Bilateral <b>Hearing Aids</b> + assistive devices.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Noise-Induced Hearing Loss (NIHL):</b> Chronic exposure (&gt; 85 dB: factories, headphones, gunfire) damaging hair cells at the basal cochlea -&gt; classic <b>\"4,000 Hz (4-kHz) Notch\"</b> on audiogram + tinnitus!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Otosclerosis:</b> Autosomal dominant abnormal spongy bone remodeling fixing the <b>Stapes Footplate in the Oval Window</b> -&gt; progressive <b>bilateral Conductive Hearing Loss</b> in <mark class=\"hl mech\"><b>young-to-middle-aged females (20–40 yrs, classically worsens during PREGNANCY!)</b></mark> + <b>\"Paracusis of Willis\"</b> (hears <i>better</i> in noisy rooms!) + normal TM (<b>Schwartze sign</b>: reddish blush behind TM) + <b>\"Carhart’s Notch\" (2,000 Hz dip)</b> on audiogram! <i>Treat:</i> Hearing aid OR <b>Surgical Stapedectomy / Stapedotomy</b>!</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u148\">← Case 7</button><button class=\"nv\" data-u=\"u150\">Case 9 →</button></nav></article><article class=\"view unit\" id=\"u150\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 9</span><h1>Vertigo Approach — BPPV, Ménièreʼs &amp; Vestibular Neuritis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Vertigo+Approach+%E2%80%94+BPPV%2C+M%C3%A9ni%C3%A8re%CA%BCs+%26+Vestibular+Neuritis\">🔍 Search on Google</a></header><h3><b>1. CRITICAL FIRST STEP: Peripheral vs. Central Vertigo (Rule Out Posterior Stroke!)</b></h3><ul>\n<li class=\"l1\"><b>Peripheral Vertigo (Inner Ear / CN VIII):</b> Sudden severe spinning, nausea/vomiting, <b>unidirectional horizontal/torsional nystagmus fatigued by visual fixation</b>, NO brain signs!</li>\n<li class=\"l1\"><b>Central Vertigo (Cerebellum / Brainstem Stroke — EMERGENCY!):</b> Gradual/constant imbalance, <b>vertical or direction-changing nystagmus NOT suppressed by fixation</b>, <b>inability to stand unsupported</b>, and <b>\"4 Ds\"</b> (Diplopia, Dysarthria, Dysphagia, Dysmetria/Ataxia) -&gt; <mark class=\"hl mech\"><b>STAT MRI Brain!</b></mark></li>\n</ul><h3><b>2. High-Yield Differentiation of the 3 Classic Peripheral Vertigos</b></h3><table class=\"t \"><tr><td><p><b>Feature</b></p></td><td><p><b>BPPV </b><i><b>(Benign Paroxysmal Positional Vertigo — #1 Overall!)</b></i></p></td><td><p><b>Vestibular Neuritis / Labyrinthitis</b></p></td><td><p><b>Ménière’s Disease</b></p></td></tr><tr><td><p><b>Pathology</b></p></td><td><p>Dislodged calcium carbonate <b>otoliths (canaliths)</b> in <b>Posterior Semicircular Canal</b>!</p></td><td><p>Post-viral inflammation of Vestibular Nerve (<b>Neuritis</b>) or Inner Ear (<b>Labyrinthitis</b>)</p></td><td><p><b>Endolymphatic Hydrops</b> (excess fluid pressure in inner ear!)</p></td></tr><tr><td><p><b>Duration of Each Spinning Episode</b></p></td><td><p><b>SECONDS (&lt; 1 Minute!)</b> — triggered ONLY by <b>rolling over in bed / looking up</b>!</p></td><td><p><b>CONTINUOUS for DAYS</b> (following recent viral URTI)</p></td><td><p><b>20 MINUTES to 12 HOURS</b> (recurrent episodic attacks!)</p></td></tr><tr><td><p><b>Hearing Loss / Tinnitus?</b></p></td><td><p><b>NO</b></p></td><td><p><i>Vestibular Neuritis:</i> <b>NO</b> | <i>Labyrinthitis:</i> <b>YES (unilateral SNHL + tinnitus!)</b></p></td><td><p><b>YES! Classic Triad:</b> <b>Episodic Vertigo + Fluctuating Low-Frequency SNHL + Roaring</b></p></td></tr><tr><td></td><td></td><td><p><b>(unilateral SNHL + tinnitus!)</b></p></td><td><p><b>Fluctuating Low-Frequency SNHL + Roaring Tinnitus + Aural Fullness</b>!</p></td></tr><tr><td><p><b>Diagnosis &amp; Treatment</b></p></td><td><p><b>Dix-Hallpike Maneuver</b> (reproduces delayed torsional nystagmus!) -&gt; <mark class=\"hl mech\"><b>EPLEY CANALITH REPOSITIONING MANEUVER</b></mark> (<b>Curative! Avoid chronic Meclizine!</b>)</p></td><td><p><b>HINTS Exam</b> (rule out central stroke!); short-term (&lt; 3 days!) <mark class=\"hl rx\"><b>Meclizine / Dimenhydrinate + Prednisone</b></mark> -&gt; early vestibular rehab!</p></td><td><p><b>Low-Salt Diet + Avoid Caffeine/Alcohol</b> + <b>Diuretics (HCTZ/Triamterene)</b> + <b>Betahistine </b>(common in Egypt!); Intratympanic Gentamicin/Steroids if refractory!</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u149\">← Case 8</button><button class=\"nv\" data-u=\"u151\">Case 10 →</button></nav></article><article class=\"view unit\" id=\"u151\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 10</span><h1>Epistaxis (NOSEBLEED — ANTERIOR VS. POSTERIOR)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Epistaxis+%28NOSEBLEED+%E2%80%94+ANTERIOR+VS.+POSTERIOR%29\">🔍 Search on Google</a></header><h3><b>1. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Local Causes (Most Common):</b> Dry nasal mucosa (dry air/AC), <b>Nose picking</b> (children!), Nasal trauma/septal deviation, Allergic/viral rhinitis, Topical nasal steroid spray aimed <i>medially</i> at septum, Cocaine, <b>Juvenile Nasopharyngeal Angiofibroma</b> (adolescent male with unilateral epistaxis + nasal mass!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Systemic Causes (Check in Recurrent / Severe / Bilateral):</b> <b>Uncontrolled Hypertension</b> (worsens bleeding!), <b>Anticoagulants / Antiplatelets</b> (Warfarin, DOACs, Aspirin, Clopidogrel), Thrombocytopenia / <b>vWD</b>, <mark class=\"hl lab\"><b>Liver Cirrhosis</b></mark> (common in Egypt!), <b>HHT</b> (Hereditary Hemorrhagic Telangiectasia / Osler-Weber-Rendu).</span></p><h3><b>2. Anatomical Separation (90% Anterior vs. 10% Posterior)</b></h3><ul>\n<li class=\"l1\"><b>Anterior Epistaxis (~90%):</b> Originates from <b>Kiesselbach’s Plexus (Little’s Area)</b> on anterior nasal septum -&gt; visible bleeding from front of nose!</li>\n<li class=\"l1\"><b>Posterior Epistaxis (~10% — Elderly/Hypertensive — HIGHEST RISK!):</b> Originates from <b>Woodruff’s Plexus (Sphenopalatine Artery)</b> -&gt; blood pours <b>down back of throat</b>, bilateral bleeding, refractory to anterior pinching!</li>\n</ul><h3><b>3. Step-by-Step Emergency Management</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>First Aid (Patient Sits UPRIGHT &amp; LEANS FORWARD — Never Tilt Head Back!):</b> Pinch <b>soft cartilaginous lower part of nose firmly for 10–15 FULL MINUTES </b>continuously without peeking! Apply cold pack to nasal bridge.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>If Still Bleeding:</b> Blow out clots gently -&gt; spray <b>Topical Vasoconstrictor (Oxymetazoline / Xylometazoline)</b> + Lidocaine on cotton pledgets for 10 min -&gt; inspect with nasal speculum &amp; headlamp!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>If Anterior Bleeding Point Visualized:</b> <b>Chemical Cauterization (Silver Nitrate Stick)</b> on <i>one side</i> of septum only (never both sides simultaneously -&gt; septal necrosis/perforation!).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>If Diffuse / No Clear Point:</b> <b>Anterior Nasal Packing</b> (Merocel sponge or Vaseline gauze lubricated with antibiotic ointment — remove in 48–72 hrs; give prophylactic Cephalexin/Amoxicillin-Clavulanate to prevent <b>Toxic Shock Syndrome</b>!).</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>If Posterior Bleeding (Still Dripping Down Throat Despite Anterior Pack!):</b> <b>Posterior Balloon Packing (Foley Catheter or Epistat Balloon)</b> -&gt; <b>Admit to Hospital (risk of hypoxia/arrhythmias!)</b> -&gt; ENT <b>Endoscopic Sphenopalatine Artery Ligation / Embolization</b>! Check <mark class=\"hl mech\"><b>BP, CBC, &amp; INR</b></mark> !</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u150\">← Case 9</button><button class=\"nv\" data-u=\"u152\">Case 11 →</button></nav></article><article class=\"view unit\" id=\"u152\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 11</span><h1>Allergic Rhinitis &amp; Non-Allergic / Rhinitis Medicamentosa</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Allergic+Rhinitis+%26+Non-Allergic+%2F+Rhinitis+Medicamentosa\">🔍 Search on Google</a></header><h3><b>1. Allergic Rhinitis</b></h3><ul>\n<li class=\"l1\"><b>Pathophysiology:</b> <b>IgE-mediated Type I Hypersensitivity</b> to inhaled allergens (dust mites, pollens, animal dander, mold).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Paroxysmal <b>sneezing</b>, <b>clear watery rhinorrhea</b>, <b>nasal itching</b>, bilateral congestion, itchy watery eyes; <b>exam shows pale, boggy, bluish-gray inferior turbinates</b>, <b>\"Allergic Shiners\"</b> (dark infraorbital circles), and <b>\"Allergic Salute\"</b> (transverse nasal crease)!</li>\n<li class=\"l1\"><b>Treatment (Ranked by Efficacy!):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl rx\"><b>Intranasal Corticosteroids (INCS — MOST EFFECTIVE SINGLE AGENT!):</b></mark> <b>Fluticasone, Mometasone, Budesonide</b> daily (aim nozzle <mark class=\"hl lab\"><b>LATERALLY toward outer corner of eye</b></mark> , away from septum! Takes 1–2 weeks for peak effect!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>2nd-Generation Oral Antihistamines</b> (<b>Cetirizine, Loratadine, Fexofenadine</b>) or <b>Intranasal Antihistamine (Azelastine)</b> (fast onset &lt; 15 min!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Saline nasal sprays</b> + Allergen avoidance; Immunotherapy (allergy shots/sublingual) if refractory.</span></p><h3><b>2. Rhinitis Medicamentosa (\"Rebound Congestion\" — Very Common OTC Trap!)</b></h3><ul>\n<li class=\"l1\"><b>Cause:</b> Overuse of <b>Topical Nasal Decongestant Sprays (Oxymetazoline / Xylometazoline)</b> for <b>&gt; 3–5 consecutive days</b> -&gt; α-receptor downregulation causes severe rebound nasal blockage!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>STOP decongestant spray immediately</b> + start <b>Intranasal Corticosteroid</b> (+ short 5-day oral steroid burst if intolerable) + Saline rinses!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u151\">← Case 10</button><button class=\"nv\" data-u=\"u153\">Case 12 →</button></nav></article><article class=\"view unit\" id=\"u153\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 12</span><h1>Acute Viral vs. Acute Bacterial Rhinosinusitis (ABRS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Viral+vs.+Acute+Bacterial+Rhinosinusitis+%28ABRS%29\">🔍 Search on Google</a></header><h3><b>1. Etiology</b></h3><ul>\n<li class=\"l1\"><b>&gt; 90–98% of Acute Sinusitis Is VIRAL</b> (Rhinovirus, Influenza, Parainfluenza, Adenovirus)!</li>\n<li class=\"l1\"><b>Secondary Bacterial (~2–10% — ABRS):</b> <i><b>Streptococcus pneumoniae</b></i>, <i><b>Haemophilus influenzae</b></i>, <i><b>Moraxella catarrhalis</b></i>.</li>\n</ul><h3><b>2. CRITICAL CLINICAL RULE: When Do You Diagnose Bacterial Sinusitis (Give Antibiotics)?</b></h3><p>Treat as <b>Acute Bacterial Rhinosinusitis (ABRS)</b> ONLY if <b>ANY 1 of 3 Criteria</b> is met:</p>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Persistent Symptoms ≥ 10 Days</b> WITHOUT improvement (nasal congestion, purulent discharge, facial pressure/pain!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Severe Onset:</b> High fever (<b>≥ 39°C</b>) + purulent discharge + facial pain for <b>≥ 3–4 consecutive days</b> from the beginning.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>\"Double Sickening\" (Worsening After Initial Improvement):</b> Symptoms initially improve after 5–6 days of viral cold, then suddenly worsen with new fever/facial pain!</span></p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ 3. Investigations &amp; Red Flags</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><b>NO Routine Sinus X-Rays or CT Scans</b> for uncomplicated acute sinusitis!</li>\n<li class=\"l1\"><b>CT Sinuses with Contrast STAT</b> if Red Flags of Orbital/Intracranial Spread: <b>Periorbital swelling, painful/restricted eye movements, vision loss (Orbital Cellulitis!)</b>, severe frontal headache/Pott’s puffy tumor, altered mental status (<b>Cavernous Sinus Thrombosis / Brain Abscess</b>)! <i>(Also rule out </i><i><b>Invasive Mucormycosis</b></i><i> [black necrotic nasal turbinates!] in </i><mark class=\"hl lab\"><i><b>Diabetic Ketoacidosis</b></i></mark><i> patients!)</i></li>\n</ul></div></div><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><b>&lt; 10 Days Mild Viral:</b> <b>NO ANTIBIOTICS!</b> Hydration, Analgesics, <b>Saline nasal irrigation</b>, <b>Intranasal steroids</b> (or ≤ 3 days Oxymetazoline).</li>\n<li class=\"l1\"><b>Confirmed ABRS:</b> <mark class=\"hl rx\"><b>Oral Amoxicillin-Clavulanate (875/125 mg BID in adults; 45–90 mg/kg/day in kids) for 5–7 days</b></mark> (or Doxycycline / Levofloxacin if severe penicillin allergy!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u152\">← Case 11</button><button class=\"nv\" data-u=\"u154\">Case 13 →</button></nav></article><article class=\"view unit\" id=\"u154\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 13</span><h1>Chronic Rhinosinusitis &amp; Nasal Polyps</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Chronic+Rhinosinusitis+%26+Nasal+Polyps\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Clinical Picture</b></h3><p>Sinonasal inflammation lasting <b>≥ 12 consecutive weeks</b> (nasal blockage, anterior/posterior nasal drip, facial fullness, <b>hyposmia/anosmia [loss of smell!]</b>), confirmed by nasal endoscopy or <b>CT Sinuses</b>.</p>\n<ul>\n<li class=\"l1\"><b>Nasal Polyps:</b> Bilateral, pale, <b>smooth, glistening, mobile, INSENSATE grape-like masses</b> arising from the ethmoid sinuses!</li>\n<li class=\"l2\"><b>TWO CLASSIC ASSOCIATIONS TO REMEMBER:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl rx\"><b>Adult with Asthma + Nasal Polyps + Aspirin/NSAID-Induced Bronchospasm:</b></mark> <mark class=\"hl rx\"><b>Samter’s Triad (AERD — Aspirin-Exacerbated Respiratory Disease)</b></mark> !</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>CHILD (&lt; 12–16 Years) With Nasal Polyps:</b> <b>RULE OUT CYSTIC FIBROSIS (Do Sweat Chloride Test!)</b>!</span></p>\n<ul>\n<li class=\"l2\"><b>UNILATERAL Bleeding/Firm Nasal Mass in Adult/Teen:</b> <b>RULE OUT TUMOR</b> (Inverted Papilloma, Squamous Cell Carcinoma, or Adolescent Male <b>Juvenile Nasopharyngeal Angiofibroma</b> -&gt; <b>NEVER biopsy JNA in clinic due to massive hemorrhage!</b>).</li>\n</ul><h3><b>2. Treatment</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl rx\"><b>Daily High-Volume Saline Nasal Irrigations + Intranasal Corticosteroids</b></mark> (drops/sprays) + short oral steroid burst for severe polyps -&gt; <b>FESS</b> (Functional Endoscopic Sinus Surgery) +/- Biologics (<b>Dupilumab</b>) if refractory eosinophilic polyps!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u153\">← Case 12</button><button class=\"nv\" data-u=\"u155\">Case 14 →</button></nav></article><article class=\"view unit\" id=\"u155\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 14</span><h1>Deviated Nasal Septum, Septal Hematoma &amp; Nasal Fracture</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Deviated+Nasal+Septum%2C+Septal+Hematoma+%26+Nasal+Fracture\">🔍 Search on Google</a></header><h3><b>1. Nasal Bone Fracture (#1 Most Common Facial Fracture!)</b></h3><ul>\n<li class=\"l1\"><b>Clinical:</b> Nasal trauma -&gt; epistaxis, swelling, external deformity, crepitus, periorbital ecchymosis.</li>\n<li class=\"l1\"><b>Investigations:</b> <b>Clinical Diagnosis — Routine Nasal X-Rays Are NOT Recommended!</b> (Order CT Face ONLY if suspecting Le Fort, orbital floor blow-out, or <b>NOE </b>[Naso-Orbito-Ethmoid] fracture!).</li>\n<li class=\"l1\"><b>Treatment:</b> Wait 3–7 days for edema to subside -&gt; <b>Closed Reduction within 7–14 days</b> (before bones fuse!).</li>\n</ul><h3><b>2. NASAL SEPTAL HEMATOMA (TRUE ENT EMERGENCY IN EVERY NASAL TRAUMA!)</b></h3><ul>\n<li class=\"l1\"><b>MUST EXAMINE INSIDE THE NOSE WITH SPECULUM/LIGHT IN EVERY NASAL INJURY!</b></li>\n<li class=\"l1\"><b>Appearance:</b> Soft, boggy, <b>bluish-purple/cherry-red tender swelling on ONE or BOTH sides of the anterior nasal septum</b> blocking the airway (does NOT shrink with Oxymetazoline!).</li>\n<li class=\"l1\"><b>Why Emergency?</b> Cuts off blood supply to septal cartilage -&gt; <b>Cartilage Necrosis within 48–72 hrs -&gt; Septal Abscess -&gt; Permanent \"Saddle-Nose\" Deformity</b> (or intracranial cavernous sinus thrombosis)!</li>\n<li class=\"l1\"><b>Action:</b> <b>IMMEDIATE Incision &amp; Drainage + Anterior Nasal Packing + Oral Antibiotics</b> (covering <i>S. aureus</i>)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u154\">← Case 13</button><button class=\"nv\" data-u=\"u156\">Case 15 →</button></nav></article><article class=\"view unit\" id=\"u156\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 15</span><h1>Pediatric Nasal Foreign Body &amp; Choanal Atresia</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Nasal+Foreign+Body+%26+Choanal+Atresia\">🔍 Search on Google</a></header><h3><b>A. Pediatric Nasal Foreign Body (CLASSIC OUTPATIENT CLUE!)</b></h3><ul>\n<li class=\"l1\"><b>Pathognomonic Presentation:</b> Child (1–5 yrs) with <b>UNILATERAL, FOUL-SMELLING, PURULENT (or blood-tinged) NASAL DISCHARGE</b>! <i>(Always suspect a hidden bead, sponge, paper, or food piece!)</i></li>\n<li class=\"l1\"><b>Treatment:</b> Spray topical Oxymetazoline + Lidocaine -&gt; try <b>\"Mother’s Kiss\" technique</b> (parent seals child’s mouth and gives a firm puff while occluding the <i>uninvolved</i> nostril!) OR extract directly with <b>right-angle hook / Katz extractor / alligator forceps</b>!</li>\n<li class=\"l1\"><b>BUTTON BATTERY IN NOSE:</b> <b>TRUE EMERGENCY</b> (causes septal perforation within hours!) -&gt; <b>STAT ENT Removal!</b></li>\n</ul><h3><b>B. Congenital Choanal Atresia (Newborn Cyanosis Clue!)</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Congenital bony/membranous blockage of posterior nasal choanae (obligate nasal breathers at birth!).</li>\n<li class=\"l1\"><b>Pathognomonic Presentation (Bilateral):</b> <b>Cyclic Cyanosis at Rest That IMMEDIATELY IMPROVES WHEN THE NEWBORN CRIES</b> (opens mouth to breathe!), and worsens during feeding! <b>Inability to pass an 8Fr suction catheter through the nose into the nasopharynx!</b></li>\n<li class=\"l1\"><i>Association:</i> <b>CHARGE Syndrome</b> (<b>C</b>oloboma, <b>H</b>eart defects, <b>A</b>tresia choanae, <b>R</b>etarded growth, <b>G</b>enital hypoplasia, <b>E</b>ar anomalies).</li>\n<li class=\"l1\"><b>Immediate Action:</b> <b>Oral Airway (McGovern nipple) / Intubation</b> -&gt; <b>CT</b> -&gt; Endoscopic surgical repair!</li>\n</ul>\n<p class=\"muted\"><i>End of Part 7A — ENT (Cases 1–15 Complete!</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u155\">← Case 14</button><button class=\"nv\" data-u=\"u157\">Case 16 →</button></nav></article><article class=\"view unit\" id=\"u157\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 16</span><h1>Acute Pharyngitis &amp; Tonsillitis (VIRAL VS. GAS — CENTOR CRITERIA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Pharyngitis+%26+Tonsillitis+%28VIRAL+VS.+GAS+%E2%80%94+CENTOR+CRITERIA%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Acute inflammation of the oropharyngeal mucosa and/or palatine tonsils, representing one of the most frequent outpatient visits in both adults and children.</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Viral (~70–85% — Most Common Overall!):</b> Rhinovirus, Adenovirus (<i>Pharyngoconjunctival fever</i>), Coronavirus, Influenza, <b>EBV</b> (Epstein-Barr Virus — <i>Infectious Mononucleosis</i>), <b>HSV</b> (Herpes Simplex Virus), Coxsackievirus (<i>Herpangina</i> — posterior vesicular ulcers!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Bacterial (~15–30% in Children, ~5–15% in Adults):</b></span></p>\n<ul>\n<li class=\"l2\"><i><b>Streptococcus pyogenes</b></i> (<b>GAS</b> — Group A Beta-Hemolytic <i>Streptococcus</i> — <b>ONLY common pathogen requiring antibiotics to prevent Acute Rheumatic Fever!</b>).</li>\n<li class=\"l2\">Rare serious bacterial causes: <i>Corynebacterium diphtheriae</i> (unvaccinated — thick gray pseudomembrane that bleeds on scraping!), <i>Neisseria gonorrhoeae</i>, <i>Fusobacterium necrophorum</i> (<b>Lemierre’s Syndrome</b>: septic internal jugular vein thrombophlebitis + septic lung emboli!).</li>\n</ul><h3><b>3. Clinical Picture &amp; Modified Centor (McIsaac) Score</b></h3><ul>\n<li class=\"l1\"><b>Viral Clues:</b> Sore throat accompanied by <b>Cough, Rhinorrhea/Coryza, Hoarseness, Conjunctivitis, or Diarrhea</b>!</li>\n<li class=\"l1\"><b>GAS Clues (Modified Centor Criteria — 1 Point Each):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Fever</b> (&gt; 38.0°C).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Absence of Cough.</b></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Tender Anterior Cervical Lymphadenopathy.</b></span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Tonsillar Swelling or Exudates.</b></span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><i>Age:</i> 3–14 yrs (<b>+1</b>), 15–44 yrs (<b>0</b>), ≥ 45 yrs (<b>−1</b>).</span></p>\n<ul>\n<li class=\"l1\"><i>Also look for GAS:</i> <b>Palatal petechiae</b>, <b>\"Strawberry tongue\"</b>, and <b>\"Sandpaper\" Scarlet Fever rash</b>!</li>\n<li class=\"l1\"><b>Infectious Mononucleosis (EBV) Trap:</b> Adolescent with severe exudative tonsillitis + <b>Posterior Cervical Lymphadenopathy + Splenomegaly + Fatigue</b> -&gt; <mark class=\"hl rx\"><b>NEVER give Amoxicillin/Ampicillin</b></mark> (triggers a classic diffuse <b>maculopapular rash</b> in ~90%!) + <b>NO contact sports for 3–4 weeks</b> (risk of fatal splenic rupture!).</li>\n</ul><h3><b>4. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Centor Score ≤ 1:</b> <b>NO Rapid Strep Test, NO Culture, NO Antibiotics!</b> (Viral -&gt; supportive care!).</li>\n<li class=\"l1\"><b>Centor Score ≥ 2–3:</b> Perform <b>RADT</b> (Rapid Antigen Detection Test — throat swab) +/- Throat Culture in children if RADT negative!</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Treatment for Confirmed GAS Pharyngitis (Prevents ARF if Started Within 9 Days!):</b></mark></li>\n<li class=\"l2\"><b>Oral Penicillin V</b> OR <mark class=\"hl rx\"><b>Oral Amoxicillin (50 mg/kg/day, max 1,000 mg/day) for 10 DAYS</b></mark> (or single <b>IM Benzathine Penicillin G</b> [1.2 million U if &gt; 27 kg; 600,000 U if ≤ 27 kg] if adherence doubtful!).</li>\n<li class=\"l2\"><i>Penicillin Allergy:</i> Cephalexin (mild non-anaphylactic) OR <mark class=\"hl rx\"><b>Azithromycin</b></mark> (5 days) / Clindamycin (if anaphylaxis).</li>\n<li class=\"l2\"><i>Symptomatic:</i> <b>Ibuprofen/Acetaminophen</b>, warm salt-water gargles, hydration!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u156\">← Case 15</button><button class=\"nv\" data-u=\"u158\">Case 17 →</button></nav></article><article class=\"view unit\" id=\"u158\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 17</span><h1>Peritonsillar Abscess (QUINSY) &amp; Retropharyngeal Abscess</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Peritonsillar+Abscess+%28QUINSY%29+%26+Retropharyngeal+Abscess\">🔍 Search on Google</a></header><h3><b>A. Peritonsillar Abscess (Quinsy — #1 Deep Neck Space Infection in Adults/Adolescents!)</b></h3><ul>\n<li class=\"l1\"><b>Pathophysiology:</b> Pus collects between the <b>tonsillar capsule</b> and the <b>superior pharyngeal constrictor muscle</b> (typically polymicrobial: <b>GAS + </b><i><b>S. aureus</b></i><b> + Oral Anaerobes</b>).</li>\n<li class=\"l1\"><b>Classic Clinical Picture (Unilateral Sore Throat Worsening After Tonsillitis!):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\">Severe unilateral throat pain + <b>Odynophagia (drooling)</b> + Fever.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>TRISMUS</b> (inability to open mouth fully due to pterygoid muscle spasm!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>\"HOT POTATO\" (Muffled) Voice</b>.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Exam:</b> Unilateral peritonsillar bulging pushing the <mark class=\"hl mech\"><b>UVULA DEVIATED TO THE OPPOSITE (HEALTHY) SIDE</b></mark> !</span></p>\n<ul>\n<li class=\"l1\"><b>Treatment:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>URGENT Needle Aspiration</b> (or <b>I&amp;D</b> [Incision &amp; Drainage] at point of maximal fluctuance) + send pus for culture!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>IV Antibiotics:</b> <mark class=\"hl rx\"><b>Ampicillin-Sulbactam</b></mark> or <mark class=\"hl rx\"><b>Ceftriaxone + Clindamycin/Metronidazole</b></mark> (followed by oral Amoxicillin-Clavulanate × 10–14 days) + <mark class=\"hl rx\"><b>IV Fluids + Single-dose IV Dexamethasone</b></mark> (reduces pain/edema dramatically!).</span></p><h3><b>B. Retropharyngeal Abscess (CRITICAL PEDIATRIC EMERGENCY &lt; 5 Years!)</b></h3><ul>\n<li class=\"l1\"><b>Pathophysiology:</b> Suppuration of retropharyngeal lymph nodes (between posterior pharyngeal wall and prevertebral fascia — spreads straight down into the <b>Superior Mediastinum -&gt; Mediastinitis!</b>).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Young child (&lt; 5 yrs) with high fever, dysphagia/drooling, muffled voice, stridor, and <mark class=\"hl lab\"><b>NECK STIFFNESS / REFUSAL TO EXTEND NECK (looks like Meningitis!)</b></mark> + bulging posterior pharyngeal wall!</li>\n<li class=\"l1\"><b>Investigations:</b> <b>Lateral Neck X-Ray (in extension &amp; inspiration)</b> shows <b>widened prevertebral soft tissue</b> (&gt; 7 mm at C2 or &gt; 14–22 mm at C6, or &gt; ½ vertebral body width!) -&gt; Confirm with <b>Contrast CT Neck</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> Protect airway -&gt; <mark class=\"hl rx\"><b>IV Ampicillin-Sulbactam (or Vancomycin + Ceftriaxone + Clindamycin)</b></mark> + <b>Emergent Surgical Intraoral Drainage in OR</b>!</li>\n</ul>\n<p>[Image Reference Suggestion]: Clinical diagram of <mark class=\"hl lab\"><b>Peritonsillar Abscess</b></mark> showing <b>Unilateral Peritonsillar Swelling + Contralateral Uvular Deviation</b>.</p><nav class=\"un\"><button class=\"nv\" data-u=\"u157\">← Case 16</button><button class=\"nv\" data-u=\"u159\">Case 18 →</button></nav></article><article class=\"view unit\" id=\"u159\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 18</span><h1>Adenotonsillar Hypertrophy &amp; Tonsillectomy Indications</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Adenotonsillar+Hypertrophy+%26+Tonsillectomy+Indications\">🔍 Search on Google</a></header><h3><b>1. Clinical Picture (Children 2–8 Years)</b></h3><ul>\n<li class=\"l1\"><b>Adenoid Hypertrophy:</b> Chronic nasal obstruction, <b>mouth breathing</b>, hyponasal speech, loud snoring, recurrent OME/sinusitis, <b>\"Adenoid Facies\"</b> (long open-mouthed face, high-arched palate, pinched nostrils). <i>(Diagnose via Lateral Neck X-ray or Flexible Nasopharyngoscopy).</i></li>\n<li class=\"l1\"><b>Tonsillar Hypertrophy:</b> Enlarged \"kissing\" tonsils causing <mark class=\"hl lab\"><b>Pediatric OSA</b></mark> (Obstructive Sleep Apnea — loud snoring, witnessed pauses/gasping, <b>hyperactivity/daytime behavioral issues mimicking ADHD</b>, secondary enuresis, failure to thrive!).</li>\n</ul><h3><b>2. Evidence-Based Indications for Adenotonsillectomy</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Pediatric OSA / Sleep-Disordered Breathing (#1 Overall Indication Today!)</b></mark> -&gt; Adenotonsillectomy cures ~80%!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Recurrent Throat Infections (Paradise Criteria — Documented in Medical Chart!):</b></span></p>\n<ul>\n<li class=\"l2\"><b>≥ 7 episodes</b> in the past <b>1 year</b>, OR</li>\n<li class=\"l2\"><b>≥ 5 episodes/year</b> for <b>2 consecutive years</b>, OR</li>\n<li class=\"l2\"><b>≥ 3 episodes/year</b> for <b>3 consecutive years</b> (with fever &gt; 38.3°C, cervical nodes, tonsillar exudate, or GAS+!).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Suspicion of Tonsillar Malignancy</b> (<b>Marked unilateral tonsillar asymmetry</b> in an adult -&gt; rule out <b>Lymphoma / SCC</b>!).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\">Recurrent <mark class=\"hl lab\"><b>Peritonsillar Abscess</b></mark> (≥ 2 episodes).</span></p>\n<ul>\n<li class=\"l1\"><b>Post-Tonsillectomy Complication Alert:</b> <b>Secondary Post-Tonsillectomy Hemorrhage</b> peaks at <b>Days 5–10 post-op</b> when the white fibrinous eschar sloughs off! <mark class=\"hl lab\"><b>EVEN A SMALL SPIT OF BRIGHT RED BLOOD POST-TONSILLECTOMY REQUIRES IMMEDIATE ER EVALUATION</b></mark> (risk of sudden catastrophic hemorrhage!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u158\">← Case 17</button><button class=\"nv\" data-u=\"u160\">Case 19 →</button></nav></article><article class=\"view unit\" id=\"u160\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 19</span><h1>Ludwigʼs Angina (BILATERAL SUBMANDIBULAR CELLULITIS — AIRWAY EMERGENCY!)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ludwig%CA%BCs+Angina+%28BILATERAL+SUBMANDIBULAR+CELLULITIS+%E2%80%94+AIRWAY+EMERGENCY%21%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Rapidly spreading, bilateral <b>gangrenous cellulitis of the submandibular, sublingual, and submental spaces</b> (floor of the mouth), <b>#1 Immediate Cause of Death = ASPHYXIATION (Airway Obstruction)!</b></p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Odontogenic Infection (~80–90% — #1 Cause!):</b> Infected <b>lower 2nd or 3rd mandibular molar teeth</b> (roots lie below mylohyoid line -&gt; pus tracks straight into submandibular space!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Other:</b> Floor-of-mouth trauma/piercing, Mandibular fracture, Sialadenitis, Poor dental hygiene / <b>DM</b> (Diabetes Mellitus).</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\">Recent toothache/extraction -&gt; fever, chills, dysphagia, drooling, <b>bilateral \"board-like\" woody induration of the submandibular neck</b>, and <b>TONGUE PUSHED UPWARD AND BACKWARD AGAINST THE PALATE (\"Double-Tongue\" Appearance)</b> + <b>Inspiratory Stridor</b>!</li>\n</ul><h3><b>4. Emergency Treatment (AIRWAY FIRST — DO NOT WAIT FOR ABSCESS FLUCTUANCE!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>IMMEDIATE AIRWAY SECURING:</b> <b>Awake Fiberoptic Nasotracheal Intubation</b> OR <b>Emergent Awake Tracheostomy</b> (do NOT paralyze with rapid-sequence induction — loss of muscle tone collapses the swollen airway!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Immediate High-Dose IV Antibiotics:</b> <mark class=\"hl rx\"><b>Ampicillin-Sulbactam</b></mark> (or <mark class=\"hl rx\"><b>Ceftriaxone + Clindamycin/Metronidazole</b></mark> ; add Vancomycin if MRSA risk) + <mark class=\"hl rx\"><b>IV Dexamethasone</b></mark> .</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Surgical Decompression &amp; Dental Extraction</b> (note: often woody cellulitis with little frank pus!).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u159\">← Case 18</button><button class=\"nv\" data-u=\"u161\">Case 20 →</button></nav></article><article class=\"view unit\" id=\"u161\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 20</span><h1>Acute &amp; Chronic Laryngitis + Vocal Cord Nodules &amp; Polyps</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+%26+Chronic+Laryngitis+%2B+Vocal+Cord+Nodules+%26+Polyps\">🔍 Search on Google</a></header><h3><b>A. Acute Laryngitis</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> <b>Viral URTI (#1!)</b> or <b>Acute Vocal Abuse</b> (shouting at football match/concert!).</li>\n<li class=\"l1\"><b>Clinical:</b> Hoarseness (<b>dysphonia</b>) or aphonia lasting <b>&lt; 3 weeks</b>, dry cough, mild throat tickle.</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Voice Rest</b> (whispering actually <i>strains</i> cords more than soft normal speech — advise silence or gentle soft voice!), <b>Steam Inhalation &amp; Hydration</b>, <b>NO ANTIBIOTICS &amp; NO ROUTINE STEROIDS</b> (unless professional singer with critical performance after laryngoscopy!).</li>\n</ul><h3><b>B. Vocal Cord Nodules (\"Singer’s / Screamer’s Nodes\") vs. Vocal Cord Polyps</b></h3><ul>\n<li class=\"l1\"><b>Vocal Cord Nodules:</b> <b>BILATERAL, symmetric, soft/firm pearly nodules</b> at the <b>junction of the anterior 1/3 and posterior 2/3</b> of the true vocal cords (point of maximal vibratory impact!) — classic in <b>teachers, singers, yelling children, and Egyptian street vendors/callers</b>! <i>Treat:</i> <b>Voice / Speech Therapy (First-Line — resolves most without surgery!)</b>.</li>\n<li class=\"l1\"><b>Vocal Cord Polyp:</b> Usually <b>UNILATERAL</b>, vascular/gelatinous polyp caused by sudden intense vocal trauma + <mark class=\"hl lab\"><b>smoking/GERD</b></mark> -&gt; requires <b>Microlaryngoscopic Surgical Excision</b> (and biopsy to rule out malignancy!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u160\">← Case 19</button><button class=\"nv\" data-u=\"u162\">Case 21 →</button></nav></article><article class=\"view unit\" id=\"u162\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 21</span><h1>Vocal Cord Paralysis (UNILATERAL VS. BILATERAL)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Vocal+Cord+Paralysis+%28UNILATERAL+VS.+BILATERAL%29\">🔍 Search on Google</a></header><h3><b>1. Etiology (Why Does the Recurrent Laryngeal Nerve [RLN] Stop Working? — Separated!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Iatrogenic Surgical Injury (#1 Overall Cause!):</b> <b>Thyroidectomy (#1!)</b>, Parathyroidectomy, <b>Anterior Cervical Spine Surgery (ACDF)</b>, Esophagectomy, Carotid endarterectomy.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Neoplastic Compression (Left RLN &gt; Right RLN Because Left Loops Around Aortic Arch!):</b> <b>Bronchogenic Carcinoma (Lung Cancer)</b>, <b>Esophageal Cancer</b>, <b>Thyroid Cancer</b>, <b>Mediastinal Lymphoma</b>!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Idiopathic / Post-Viral (~20–30%)</b>, Thoracic Aortic Aneurysm, Left Atrial Enlargement in Mitral Stenosis (<b>Ortner’s Syndrome</b>).</span></p><h3><b>2. Crucial Clinical Comparison: Unilateral vs. Bilateral RLN Paralysis</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Type</b></p></th><th><p><b>Vocal Cord Position</b></p></th><th><p><b>Classic Clinical Presentation</b></p></th><th><p><b>Management</b></p></th></tr><tr><td><p><b>Unilateral RLN Paralysis</b></p></td><td><p>One cord fixed in <b>Paramedian </b>position</p></td><td><p><b>Breathy, weak, hoarse voice</b>, weak cough, <b>aspiration</b> with liquids (<mark class=\"hl lab\"><b> AIRWAY IS PATENT!</b></mark> )</p></td><td><p><b>Flexible Laryngoscopy</b> + <b>CT Neck &amp; Chest (Skull base to Aortic Arch!)</b> to rule out <b>Lung/Mediastinal/Thyroid Tumor</b>! Speech therapy -&gt; <b>Vocal Cord Medialization (Injection/Thyroplasty)</b> if persistent &gt; 6–12 mos!</p></td></tr><tr><td><p><b>Bilateral RLN Paralysis</b> <i>(e.g., Post-Total Thyroidectomy!)</i></p></td><td><p><b>BOTH cords fixed near Midline</b>!</p></td><td><p><b>SEVERE INSPIRATORY STRIDOR &amp; ACUTE ASPHYXIATION </b>(ironically voice may sound nearly normal!)</p></td><td><p><mark class=\"hl lab\"><b>LIFE-THREATENING AIRWAY EMERGENCY!</b></mark> <b>Immediate Intubation -&gt; Tracheostomy</b> (+/- later Laser Arytenoidectomy/Cordotomy)!</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u161\">← Case 20</button><button class=\"nv\" data-u=\"u163\">Case 22 →</button></nav></article><article class=\"view unit\" id=\"u163\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 22</span><h1>Laryngeal Carcinoma (THE HOARSENESS RED FLAG!)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Laryngeal+Carcinoma+%28THE+HOARSENESS+RED+FLAG%21%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Etiology</b></h3><p><b>Squamous Cell Carcinoma (SCC &gt; 95%)</b> of the larynx (<b>Glottic [true vocal cords] ~60% &gt; Supraglottic ~35% &gt; Subglottic &lt; 5%</b>).</p>\n<ul>\n<li class=\"l1\"><b>Risk Factors (Synergistic!):</b> <b>Heavy Tobacco Smoking (Cigarettes/Shisha) + Alcohol Consumption</b> (90%+ of cases!), HPV (rarely), GERD/LPR, Radiation.</li>\n</ul><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ 2. THE GOLDEN ENT RED FLAG RULE!</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>ANY HOARSENESS PERSISTING &gt; 2–4 WEEKS (ESPECIALLY IN A SMOKER &gt; 40 YEARS OLD) = LARYNGEAL CARCINOMA UNTIL PROVEN OTHERWISE BY FLEXIBLE LARYNGOSCOPY!</b></mark></li>\n<li class=\"l1\"><i>Glottic Cancer:</i> Presents <b>EARLY with Hoarseness</b> (minimal lymphatics -&gt; rare early metastasis -&gt; <b>best prognosis!</b>).</li>\n<li class=\"l1\"><i>Supraglottic Cancer:</i> Presents <b>LATE</b> with <b>dysphagia, referred ear pain (otalgia via CN X!)</b>, muffled voice, and <b>palpable cervical lymph node metastases</b>!</li>\n</ul></div></div><h3><b>3. Diagnosis &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Office Flexible Laryngoscopy</b> -&gt; <b>Direct Microlaryngoscopy + Biopsy under Anesthesia</b> + <b>CT Neck &amp; Chest</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> <i>Early Glottic (T1–T2):</i> <b>Transoral Laser Microsurgery</b> OR <b>Definitive Radiation Therapy</b> (both preserve voice with ~90% cure!). <i>Advanced (T3–T4): </i><b>Chemoradiation (organ preservation)</b> or <b>Total Laryngectomy</b> (+ neck dissection &amp; permanent tracheostoma)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u162\">← Case 21</button><button class=\"nv\" data-u=\"u164\">Case 23 →</button></nav></article><article class=\"view unit\" id=\"u164\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 23</span><h1>Nasopharyngeal Carcinoma (NPC)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Nasopharyngeal+Carcinoma+%28NPC%29\">🔍 Search on Google</a></header><h3><b>1. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>EBV</b> (Epstein-Barr Virus) latent infection (classic <b>Undifferentiated Non-Keratinizing Carcinoma</b>!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Environmental / Dietary:</b> Salted preserved fish/nitrosamines, smoking.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Bimodal Age:</b> Young adults (20–30s) &amp; older adults (50–60s).</span></p><h3><b>2. Clinical Picture (Classic Triad in a Young/Middle-Aged Adult!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Painless Upper/Posterior Cervical Lymphadenopathy (#1 Initial Presentation!)</b>.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Unilateral Conductive Hearing Loss / Unilateral Otitis Media with Effusion (OME)</b> (tumor blocks Eustachian tube in <b>Fossa of Rosenmüller</b>!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Unilateral Nasal Obstruction &amp; Blood-Tinged Nasal Discharge / Epistaxis</b> (+ late <b>CN VI diplopia</b> or facial numbness from skull base invasion!).</span></p><h3><b>3. Diagnosis &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Flexible Nasopharyngoscopy + Biopsy</b> + <mark class=\"hl mech\"><b>MRI Skull Base/Neck</b></mark> + <b>EBV DNA titer</b>.</li>\n<li class=\"l1\"><b>Treatment (Surgery Is NOT Primary Because of Skull Base Location — Extremely Radiosensitive!):</b> <b>Radiation Therapy</b> (early Stage I) or <b>Concurrent Cisplatin Chemoradiation</b> (Stages II–IV)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u163\">← Case 22</button><button class=\"nv\" data-u=\"u165\">Case 24 →</button></nav></article><article class=\"view unit\" id=\"u165\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 24</span><h1>Neck Masses Approach (&quot;RULE OF 7s&quot; &amp; CONGENITAL CYSTS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Neck+Masses+Approach+%28%22RULE+OF+7s%22+%26+CONGENITAL+CYSTS%29\">🔍 Search on Google</a></header><h3><b>1. Diagnostic Mindset (Age + Location + Time Rule!)</b></h3><ul>\n<li class=\"l1\"><b>\"Rule of 7s\" for Persistent Non-Infectious Neck Mass:</b> Present <b>7 days</b> = Inflammatory | <b>7 months</b> = Neoplastic | <b>7 years</b> = Congenital!</li>\n<li class=\"l1\"><b>Pediatric Neck Mass:</b> ~90% <b>Benign</b> (Reactive lymphadenitis, Congenital cyst).</li>\n<li class=\"l1\"><b>Adult &gt; 40 Years With Persistent Painless Lateral Neck Mass (&gt; 2–3 Weeks):</b> <b>~80% MALIGNANT</b> (Metastatic Head &amp; Neck <b>SCC</b> or <mark class=\"hl lab\"><b>Lymphoma</b></mark> ) until proven otherwise! <i>(Perform </i><i><b>FNA</b></i><i> [Fine-Needle Aspiration] + </i><i><b>Panendoscopy</b></i><i> — </i><i><b>NEVER do an open excisional biopsy of a suspicious adult neck node before FNA &amp; mucosal exam</b></i><i>, as it violates tumor planes!)</i></li>\n</ul><h3><b>2. Classic Congenital Neck Masses (Midline vs. Lateral!)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Mass &amp; Location</b></p></th><th><p><b>Embryologic Origin</b></p></th><th><p><b>Pathognomonic Exam Clue</b></p></th><th><p><b>Treatment</b></p></th></tr><tr><td><p><b>Thyroglossal Duct Cyst</b> <i>(#1 Congenital Neck Mass — </i><i><b>MIDLINE </b></i><i>below hyoid bone!)</i></p></td><td><p>Remnant of thyroid descent tract (foramen cecum -&gt; neck)</p></td><td><p>Painless <b>MIDLINE</b> cyst that <mark class=\"hl lab\"><b>MOVES UPWARD BOTH WITH SWALLOWING AND WITH TONGUE PROTRUSION!</b></mark></p></td><td><p>Ultrasound (confirm normal thyroid gland in neck!) -&gt; <b>Sistrunk Procedure</b> (excise cyst + tract + <b>central body of hyoid bone</b> to prevent recurrence!)</p></td></tr><tr><td><p><b>Branchial Cleft Cyst</b> <i>(</i><i><b>2nd Cleft #1</b></i><i> — </i><i><b>LATERAL</b></i><i> neck along anterior border of SCM!)</i></p></td><td><p>Failure of 2nd branchial cleft obliteration</p></td><td><p>Smooth, painless fluctuant mass at <b>junction of upper 1/3 &amp; lower 2/3 of anterior SCM</b> in young adults (often swells after URTI!)</p></td><td><p><b>Rule out Cystic Metastatic HPV+ Tonsil Cancer</b> via FNA/CT in adults &gt; 40 -&gt; <b>Complete Surgical Excision</b>!</p></td></tr><tr><td><p><b>Cystic Hygroma (Lymphangioma) </b><i>(</i><i><b>Posterior Triangle</b></i><i> — Infants &lt; 2 yrs!)</i></p></td><td><p>Malformed dilated lymphatic sacs</p></td><td><p>Soft, compressible, <b>BRILLIANTLY TRANSLUMINATING</b> mass in <b>posterior triangle</b> (associated with <b>Turner Syndrome</b>!)</p></td><td><p>Surgical excision and/or <b>Sclerotherapy </b>(Bleomycin/Doxycycline)</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u164\">← Case 23</button><button class=\"nv\" data-u=\"u166\">Case 25 →</button></nav></article><article class=\"view unit\" id=\"u166\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 25</span><h1>Salivary Gland Disorders — Sialolithiasis &amp; Suppurative Parotitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Salivary+Gland+Disorders+%E2%80%94+Sialolithiasis+%26+Suppurative+Parotitis\">🔍 Search on Google</a></header><h3><b>A. Sialolithiasis (Salivary Duct Stones — &gt; 80% in SUBMANDIBULAR [Wharton’s] DUCT!)</b></h3><ul>\n<li class=\"l1\"><b>Why Submandibular Gland?</b> Longer upward-draining <b>Wharton’s duct</b> + thicker alkaline mucoid calcium-rich saliva!</li>\n<li class=\"l1\"><b>Classic Symptom:</b> Recurrent painful <b>swelling under the jaw triggered IMMEDIATELY BEFORE OR DURING EATING (\"Mealtime Syndrome\")</b>, slowly subsiding over 1–2 hours!</li>\n<li class=\"l1\"><b>Exam:</b> Bimanual palpation of floor of mouth feels a <b>hard stone</b> along Wharton’s duct; pus or zero saliva expressed from submandibular papilla!</li>\n<li class=\"l1\"><b>Treatment:</b> Hydration, sour sialogogues (lemon drops!), warm massage, NSAIDs (small stones pass spontaneously!); if persistent -&gt; <b>Sialendoscopy / Transoral Ductal Stone Removal</b> (or gland excision if deep intraglandular!).</li>\n</ul><h3><b>B. Acute Suppurative Parotitis</b></h3><ul>\n<li class=\"l1\"><b>Classic Patient:</b> <b>Elderly, Dehydrated, Post-Operative, or Debilitated ICU Patient</b> (dry mouth -&gt; retrograde <i><b>Staphylococcus aureus</b></i> infection up <b>Stensen’s duct</b>!).</li>\n<li class=\"l1\"><b>Clinical:</b> Sudden warm, exquisitely tender, erythematous unilateral parotid swelling (earlobe pushed out!) + fever + <b>pus expressed from Stensen’s duct orifice opposite upper 2nd molar</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> <mark class=\"hl rx\"><b>IV Hydration + IV Anti-Staph Antibiotics (Vancomycin / Nafcillin / Cefazolin + Metronidazole)</b></mark> + warm compresses + sialogogues (<b>I&amp;D</b> if abscess forms on CT/US!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u165\">← Case 24</button><button class=\"nv\" data-u=\"u167\">Case 26 →</button></nav></article><article class=\"view unit\" id=\"u167\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 26</span><h1>Salivary Gland Tumors (&quot;80% RULE&quot;)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Salivary+Gland+Tumors+%28%2280%25+RULE%22%29\">🔍 Search on Google</a></header><h4><b>The Classic \"80% Rule\" of Salivary Neoplasms</b></h4><ul>\n<li class=\"l1\"><b>80%</b> occur in the <b>Parotid Gland</b> (where <b>80% are BENIGN</b>!).</li>\n<li class=\"l1\"><b>50%</b> of <b>Submandibular</b> &amp; <b>&gt; 70–80%</b> of <b>Minor Salivary Gland (Palate)</b> tumors are <b>MALIGNANT</b>! <i>(Smaller gland = Higher malignancy risk!)</i></li>\n</ul><h4><b>Major Tumors (Separated)</b></h4><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Pleomorphic Adenoma (Benign Mixed Tumor — #1 Overall Salivary Tumor!):</b> Slow-growing, painless, firm mobile mass in <b>Parotid tail</b> (intact <b>CN VII Facial Nerve!</b>). <i>Treat:</i> <b>Superficial Parotidectomy</b> preserving CN VII (<b>NEVER simple enucleation</b> — high recurrence &amp; risk of malignant transformation!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Warthin’s Tumor (Papillary Cystadenoma Lymphomatosum):</b> <b>Older MALE SMOKERS</b>, <b>~10–15% BILATERAL</b> parotid masses!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Mucoepidermoid Carcinoma (#1 Malignant Salivary Tumor!) &amp; Adenoid Cystic Carcinoma</b> (notorious for <b>Perineural Invasion</b> -&gt; pain/facial palsy &amp; late lung mets!):</span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl mech\"><b>MALIGNANCY RED FLAGS:</b></mark> <b>CN VII Facial Nerve Weakness/Palsy</b>, Rapid growth, <b>Pain</b>, Hard fixed mass, Skin ulceration, Cervical nodes -&gt; <b>Superficial/Total Parotidectomy +/- Neck Dissection + Radiation</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u166\">← Case 25</button><button class=\"nv\" data-u=\"u168\">Case 27 →</button></nav></article><article class=\"view unit\" id=\"u168\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 27</span><h1>Dysphagia &amp; Esophageal Foreign Body / Button Battery Emergency</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dysphagia+%26+Esophageal+Foreign+Body+%2F+Button+Battery+Emergency\">🔍 Search on Google</a></header><p><mark class=\"hl dx\"><b>1. Pediatric &amp; Adult Esophageal Foreign Body (3 Normal Narrowings: Cricopharyngeus [C6 — #1!], Aortic Arch [T4], LES [T10])</b></mark></p>\n<ul>\n<li class=\"l1\"><b>Symptoms:</b> Sudden drooling, dysphagia, gagging, chest pain, refusal to feed!</li>\n<li class=\"l1\"><b>X-RAY CLUE (AP + Lateral Chest/Neck X-Ray):</b></li>\n<li class=\"l2\"><b>Coins in Esophagus:</b> Seen <b>EN FACE (full circle)</b> on AP view (because esophagus is flattened AP, unlike trachea where coins sit edge-on!).</li>\n<li class=\"l2\"><b>BUTTON BATTERY vs. COIN (CRITICAL DISTINCTION!):</b> Button battery shows a <b>\"DOUBLE-RING / HALO SIGN\"</b> on AP view and a <b>\"Step-Off\"</b> on lateral view!</li>\n</ul><h3><b>2. BUTTON BATTERY IN ESOPHAGUS = EXTREME LIFE-THREATENING EMERGENCY (&lt; 2 HOURS TO NECROSIS!)</b></h3><ul>\n<li class=\"l1\"><b>Why Fatal?</b> Electrical current generates hydroxide ions -&gt; <b>rapid liquefactive necrosis within 2 HOURS</b>, eroding into <b>Aorta (fatal Aortoesophageal Fistula!)</b> or <b>Trachea (Tracheoesophageal Fistula)</b>!</li>\n<li class=\"l1\"><b>IMMEDIATE ACTION:</b> <mark class=\"hl mech\"><b>DO NOT WAIT FOR NPO FASTING RULES!</b></mark> Give <b>Honey</b> (10 mL q10 min if age &gt; 1 yr &amp; &lt; 12 hrs post-ingestion — coats battery!) -&gt; <b>EMERGENT ENDOSCOPIC REMOVAL WITHIN 2 HOURS!</b> <i>(Also remove magnets urgently if &gt; 1 magnet or magnet + metal!)</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u167\">← Case 26</button><button class=\"nv\" data-u=\"u169\">Case 28 →</button></nav></article><article class=\"view unit\" id=\"u169\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 28</span><h1>Caustic Esophageal Ingestion (ALKALI VS. ACID)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Caustic+Esophageal+Ingestion+%28ALKALI+VS.+ACID%29\">🔍 Search on Google</a></header><ul>\n<li class=\"l1\"><b>Alkali (Drain cleaners / Lye / Bleach — WORSE for Esophagus!):</b> Causes <mark class=\"hl lab\"><b>LIQUEFACTIVE NECROSIS</b></mark> penetrating deep through esophageal muscle -&gt; perforation &amp; severe <b>fibrotic esophageal strictures</b>!</li>\n<li class=\"l1\"><b>Acid (Toilet/Battery cleaners):</b> Causes <mark class=\"hl lab\"><b>COAGULATIVE NECROSIS</b></mark> (forms protective eschar; tends to pool and injure <b>stomach/antrum</b> more!).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>IMMEDIATE ER MANAGEMENT:</b></mark></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Airway FIRST</b> (inspect for stridor/oropharyngeal burns -&gt; early intubation!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>CONTRAINDICATIONS (DO NOT DO!):</b> <b>NO Induced Vomiting (Emesis)</b>, <b>NO Activated Charcoal</b> (obscures endoscopy!), <b>NO Neutralizing Acids/Bases </b>(exothermic heat worsens burn!), <b>NO Blind NG Tube Insertion</b>!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl rx\"><b>NPO + IV Fluids + IV PPI</b></mark> -&gt; <mark class=\"hl rx\"><b>Early Upper GI Endoscopy (EGD) within 12–24 Hours</b></mark> (grades mucosal injury Zargar I–III to predict stricture risk — <i>avoid EGD after 48–72 hrs due to perforation risk!</i>). Monitor long-term for <b>Esophageal Squamous Cell Carcinoma</b>!</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u168\">← Case 27</button><button class=\"nv\" data-u=\"u170\">Case 29 →</button></nav></article><article class=\"view unit\" id=\"u170\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 29</span><h1>Facial Nerve (CN VII) Palsy — Bellʼs Palsy vs. Central Stroke</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Facial+Nerve+%28CN+VII%29+Palsy+%E2%80%94+Bell%CA%BCs+Palsy+vs.+Central+Stroke\">🔍 Search on Google</a></header><h3><b>1. CRITICAL FIRST DIFFERENTIATION: LMN (Peripheral) vs. UMN (Central Stroke)</b></h3><ul>\n<li class=\"l1\"><b>UMN (Central — e.g., Contralateral MCA Stroke):</b> Forehead is <b>SPARED</b> (bilateral cortical innervation to upper face!) -&gt; <b>Lower face paralysis ONLY</b> + arm/leg weakness or aphasia!</li>\n<li class=\"l1\"><b>LMN (Peripheral — e.g., Bell’s Palsy, Ramsay Hunt, Parotid Tumor, Cholesteatoma, Mastoiditis):</b> <b>ENTIRE IPSILATERAL HALF OF FACE PARALYZED (CANNOT wrinkle forehead, CANNOT close eye, drooping mouth!)</b>!</li>\n</ul><h3><b>2. Bell’s Palsy (Idiopathic Acute LMN CN VII Palsy — HSV-1 Reactivation!)</b></h3><ul>\n<li class=\"l1\"><b>Clinical:</b> Rapid onset (&lt; 48–72 hrs) of unilateral complete facial weakness (<b>forehead + eye + mouth</b>), <b>hyperacusis</b> (stapedius paralysis), loss of taste on <b>anterior 2/3 of tongue</b>, retroauricular ache. <i>(Check ear canal for vesicles = </i><i><b>Ramsay Hunt Syndrome [VZV]</b></i><i>!)</i></li>\n<li class=\"l1\"><b>Diagnosis:</b> <b>Clinical Diagnosis of Exclusion!</b> (<mark class=\"hl mech\"><b> NO routine Brain CT/MRI or labs needed</b></mark> if typical acute isolated Bell’s palsy!).</li>\n<li class=\"l1\"><b>Treatment (Start Within 72 Hours!):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl rx\"><b>Oral Corticosteroids (MOST IMPORTANT!):</b></mark> <mark class=\"hl rx\"><b>Prednisolone 60 mg/day × 5 days, then taper over 5 days</b></mark> (improves complete recovery from ~70% to &gt; 85– 90%!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i>(Optional in severe complete paralysis or Ramsay Hunt):</i> Add <mark class=\"hl rx\"><b>Valacyclovir / Acyclovir</b></mark> × 7 days (<i>mandatory in Ramsay Hunt!</i>).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>MANDATORY EYE PROTECTION (Prevents Corneal Ulcer &amp; Blindness!):</b> Frequent <b>lubricating artificial tears</b> by day + <b>thick lubricating ointment + taping eyelid shut at night</b>!</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u169\">← Case 28</button><button class=\"nv\" data-u=\"u171\">Case 30 →</button></nav></article><article class=\"view unit\" id=\"u171\" hidden style=\"--c:#0097a7\"><button class=\"back\" data-p=\"7\">← ENT</button><header class=\"uh\"><span class=\"ul\">Case 30</span><h1>Tracheostomy Care &amp; Acute Tracheostomy Emergencies</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Tracheostomy+Care+%26+Acute+Tracheostomy+Emergencies\">🔍 Search on Google</a></header><h3><b>1. Indications for Tracheostomy</b></h3><p>Prolonged mechanical ventilation (&gt; 7–14 days), Upper airway obstruction (tumor, bilateral RLN palsy, Ludwig’s), Airway protection/secretion clearance, Obstructive sleep apnea (refractory).</p><h3><b>2. THE 3 LIFE-THREATENING TRACHEOSTOMY EMERGENCIES (Every Ward &amp; ICU Doctor Must Know!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Acute Tube Obstruction (Mucus Plug / Blood Clot):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Signs:</i> Sudden severe respiratory distress, high ventilator peak pressures, inability to pass suction catheter!</li>\n<li class=\"l2\"><i>Action:</i> <b>Remove &amp; clean Inner Cannula IMMEDIATELY</b> + suction! If still blocked -&gt; <b>Deflate cuff and REMOVE entire tracheostomy tube</b>, bag-mask ventilate over mouth/nose (or stoma!) and reinsert spare tube!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Accidental Decannulation (Tube Falls Out!):</b></span></p>\n<ul>\n<li class=\"l2\"><i>CRITICAL TIMING RULE:</i></li>\n<li class=\"l1\"><b>&lt; 7 Days Post-Op (Immature Tract!):</b> <b>DO NOT blindly shove the tube back into the neck</b> (creates a fatal false passage in pretracheal fascia!) -&gt; <mark class=\"hl lab\"><b>Intubate OROTRACHEALLY from above</b></mark> (or summon ENT)!</li>\n<li class=\"l1\"><b>&gt; 7–10 Days Post-Op (Mature Tract):</b> Gently reinsert same-size (or 1 size smaller) tube using obturator -&gt; confirm <b>ETCO2</b> &amp; bilateral breath sounds!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Tracheoinnominate Artery Fistula (TIF — Weeks 1–4 Post-Op — &gt; 75% Fatal Without Instant Action!):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Warning:</i> <b>\"Sentinel Bleed\"</b> (small bright red hemoptysis/pulsating tube) followed by massive catastrophic tracheal hemorrhage!</li>\n<li class=\"l2\"><i>LIFE-SAVING MANEUVER (</i><i><b>Utley Maneuver</b></i><i>):</i> <b>Over-inflate tracheostomy cuff maximally</b> first -&gt; if bleeding continues, <b>insert gloved finger directly through stoma and compress the Innominate Artery ANTERIORLY upward against the posterior sternum</b> while rushing to OR!</li>\n</ul>\n<p class=\"muted\"><i>End of Part 7B — ENT (30 Cases Complete!)</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u170\">← Case 29</button></nav></article>"});
